// Graphite Whisper — a fixed vector is progressively drawn, then erased; no jitter.
const FLOW = 2;
const SIZE = 18;
const FADE = 0;
const SPEED = 50;
const LINKS = 0;
const TERRITORY = 0;
const REBUILD_PHOTO = 1;
const PHOTO_OPACITY = 100;
const PHOTO_BLUR = 0;

function ease(a, b, value) {
  const x = Math.max(0, Math.min(1, (value - a) / (b - a)));
  return x * x * (3 - 2 * x);
}

function brush(point, stroke, t) {
  const marks = [];
  for (let i = 0; i < FLOW; i += 1) {
    const seed = point.index * 29 + i * 13 + stroke.seed * 83;
    const c = photo(point.x, point.y, PHOTO_BLUR);
    if (!c) continue;
    marks.push({
      x: point.x + (rand(seed) - .5) * 7,
      y: point.y + (rand(seed + 5) - .5) * 7,
      size: SIZE * (.7 + rand(seed + 11) * .55) * 2.2,
      alpha: .22 * PHOTO_OPACITY / 100,
      red: c.red, green: c.green, blue: c.blue,
      shape: "streak",
      angle: point.angle * 180 / Math.PI + (rand(seed + 19) - .5) * 18,
      soft: .2
    });
  }
  return marks;
}

function move(mark, t) {
  const speed = .075 + mark.seed * .055;
  const cycle = (t * speed + mark.seed) % 1;
  const drawn = ease(.04, .27, cycle);
  const erased = ease(.7, .9, cycle);
  return {
    dx: 0,
    dy: 0,
    size: Math.max(0, drawn - erased),
    alpha: drawn > erased ? .34 : 0
  };
}
